// Runs the simulation off the main thread and draws it straight to an OffscreenCanvas.
import type { CompiledGame, EngineOptions, GameEngine } from '../../../game/contracts';
import { createEngine } from '../../../game/game';
import { createEvaluator } from '../../../game/interpreter/interpreter';
import { CANVAS_DIMS } from '../canvas';
import type { Location } from '../types';
import { drawGame } from './draw';
import Loop from './loop';

export type ElementInfo = { name: string; color: string };

export type GameWorkerRequest =
  | CanvasRequest
  | NewGameRequest
  | PaintRequest
  | EraseRequest
  | PauseRequest
  | ClearRequest;
export type CanvasRequest = { type: 'canvas'; canvas: OffscreenCanvas };
export type NewGameRequest = { type: 'game'; game: CompiledGame };
export type PaintRequest = { type: 'paint'; cells: Location[]; elementName: string };
export type EraseRequest = { type: 'erase'; cells: Location[] };
export type PauseRequest = { type: 'pause'; paused: boolean };
export type ClearRequest = { type: 'clear' };

export type GameWorkerResponse =
  | { type: 'game'; elements: ElementInfo[] }
  | { type: 'stats'; tick: number; count: number }
  | { type: 'error'; message: string };

const loop = new Loop();
let ctx: OffscreenCanvasRenderingContext2D | null = null;
let compiled: CompiledGame | null = null;
let game: GameEngine | null = null;
let paused = false;
let failed = false;

const post = (message: GameWorkerResponse) => self.postMessage(message);

function makeEngine(source: CompiledGame) {
  const options: EngineOptions = { width: CANVAS_DIMS.x, height: CANVAS_DIMS.y };
  game = createEngine(source, options, createEvaluator());
  failed = false;
  redraw();
}

function redraw() {
  if (ctx && game) drawGame(ctx, game.snapshot());
  else if (ctx) ctx.clearRect(0, 0, CANVAS_DIMS.x, CANVAS_DIMS.y);
}

function fail(error: unknown) {
  failed = true;
  post({ type: 'error', message: error instanceof Error ? error.message : String(error) });
}

function colorOf(source: CompiledGame, name: string): string {
  const element = source.elements.get(name);
  const field = [...(element?.fieldInitializers ?? [])].reverse().find((f) => f.varName.value === 'color');
  return field?.value?.type === 'Color' ? field.value.value : '#9a9a9a';
}

loop.callback = () => {
  if (!game || !ctx || paused || failed) return;
  try {
    const snapshot = game.step();
    drawGame(ctx, snapshot);
    if (snapshot.tick % 10 === 0) post({ type: 'stats', tick: snapshot.tick, count: snapshot.elements.length });
  } catch (error) {
    fail(error);
  }
};

self.onmessage = (event: MessageEvent<GameWorkerRequest>) => {
  const data = event.data;
  switch (data.type) {
    case 'canvas':
      ctx = data.canvas.getContext('2d');
      loop.start();
      redraw();
      break;
    case 'game':
      compiled = data.game;
      try {
        makeEngine(compiled);
        const elements = game!.availableElements().map((name) => ({ name, color: colorOf(compiled!, name) }));
        post({ type: 'game', elements });
        post({ type: 'stats', tick: 0, count: 0 });
      } catch (error) {
        fail(error);
      }
      break;
    case 'paint':
      if (!game || failed) return;
      for (const { x, y } of data.cells) {
        if (x < 0 || y < 0 || x >= CANVAS_DIMS.x || y >= CANVAS_DIMS.y) continue;
        try {
          game.place(data.elementName, x, y);
        } catch (error) {
          if (error instanceof Error && /occupied/.test(error.message)) continue;
          fail(error);
          return;
        }
      }
      if (paused) redraw();
      break;
    case 'erase':
      if (!game) return;
      for (const { x, y } of data.cells) {
        if (x < 0 || y < 0 || x >= CANVAS_DIMS.x || y >= CANVAS_DIMS.y) continue;
        game.erase(x, y);
      }
      if (paused || failed) redraw();
      break;
    case 'pause':
      paused = data.paused;
      break;
    case 'clear':
      if (compiled) makeEngine(compiled);
      post({ type: 'stats', tick: 0, count: 0 });
      break;
  }
};
